  @media (max-width: #{$breakpoint-md - 1px}) {
    padding: $space-4;
    align-items: flex-start;
  }
}

// ============================================
// Auth Container Block
// ============================================
.auth-container {
  width: 100%;
  max-width: 420px;
  padding: $space-8;
  background: $surface;
  border: 1px solid $line;
  border-radius: $radius-xl;
  box-shadow: $shadow-card;

  @media (max-width: #{$breakpoint-md - 1px}) {
    padding: $space-5 $space-4;
  }

  &.wide {
    max-width: 680px;
  }

  h2 {
    @include text-title;
    text-align: center;
    margin-bottom: $space-4;
    color: $ink;
  }
}

// ============================================
// Toggle Button
// ============================================
.toggle-btn {
  display: block;
  width: 100%;
  min-height: $ctl-h;
  padding: $space-2 $space-4;
  margin-bottom: $space-6;
  background: $surface;
  border: 1px solid $line;
  border-radius: $radius-md;
  color: $ink;
  font-size: $font-size-base;
  font-weight: $font-weight-medium;
  cursor: pointer;
  transition: background $transition-base, border-color $transition-base;

  &:hover {
    background: $page;
    border-color: #C9D2DE;
  }

  &:focus-visible {
    outline: none;
    box-shadow: $focus-ring;
  }
}

// ============================================
// Auth Form Block
// ============================================
.auth-form {
  display: flex;
  flex-direction: column;
  gap: $space-4;

  label {
    display: flex;
    flex-direction: column;
    gap: $space-2;
    font-size: $font-size-base;
    font-weight: $font-weight-medium;
    color: $ink-2;
  }

  input,
  select {
    min-height: $ctl-h;
    padding: $space-2 $space-3;
    background: $surface;
    border: 1px solid #C9D2DE;
    border-radius: $radius-md;
    color: $ink;
    font-size: $font-size-md;
    transition: border-color $transition-base, box-shadow $transition-base;

    &:focus {
      outline: none;
      border-color: $blue-600;
      box-shadow: $focus-ring;
    }
  }

  input::placeholder {
    color: $ink-2;
  }

  select {
    cursor: pointer;
  }

  button[type="submit"] {
    margin-top: $space-2;
    min-height: $ctl-h;
    padding: $space-3 $space-4;
    background: $blue-600;
    border: 1px solid transparent;
    border-radius: $radius-md;
    color: #ffffff;
    font-size: $font-size-md;
    font-weight: $font-weight-semibold;
    cursor: pointer;
    transition: background $transition-base;

    &:hover:not(:disabled) {
      background: $blue-700;
    }

    &:focus-visible {
      outline: none;
      box-shadow: $focus-ring;
    }

    &:disabled {
      opacity: 0.55;
      cursor: not-allowed;
    }
  }
}

// ============================================
// Register Grid (symmetric two-column layout)
// ============================================
.register-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: $space-4 $space-5;

  label {
    margin: 0;
  }

  .span-2 {
    grid-column: 1 / -1;
  }

  .section-title {
    margin: $space-2 0 0;
    padding-top: $space-4;
    border-top: 1px solid $line;
    color: $ink;
    font-size: $font-size-md;
    font-weight: $font-weight-semibold;
  }

  .section-hint {
    margin: 0;
    color: $ink-2;
    font-size: $font-size-xs;
  }

  button[type="submit"] {
    width: 100%;
  }

  @media (max-width: 639px) {
    grid-template-columns: minmax(0, 1fr);
  }
}

