@use '../../../styles/variables' as *;

// ── Reset & base ──────────────────────────────────────────────────────────────
:host {
  display: block;
  font-family: $font-family-base;
  font-size: $font-size-md;
  color: $ink;
  background: $page;
  -webkit-font-smoothing: antialiased;
}

*, *::before, *::after { box-sizing: border-box; }

a { text-decoration: none; }

// ── Shared layout ─────────────────────────────────────────────────────────────
.section-inner {
  max-width: $container-max-width;
  margin: 0 auto;
  padding: 0 $container-padding;

  @media (max-width: #{$breakpoint-md - 1px}) { padding: 0 $container-padding-mobile; }
}

.section-title {
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 700;
  color: $ink;
  text-align: center;
  margin: 0 0 $space-3;
  letter-spacing: -0.3px;
}

.section-subtitle {
  font-size: $font-size-md;
  color: $ink-2;
  text-align: center;
  margin: 0;
  line-height: 1.6;
}

// ── Buttons ───────────────────────────────────────────────────────────────────
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: $space-2;
  border: 1px solid transparent;
  border-radius: $radius-md;
  font-family: inherit;
  font-weight: 600;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
  min-height: $ctl-h;
  padding: $space-3 $space-5;
  font-size: $font-size-md;
  text-align: center;

  &:focus-visible { outline: none; box-shadow: $focus-ring; }

  &--primary {
    background: $blue-600;
    color: #fff;
    &:hover { background: $blue-700; }
  }

  &--outline {
    background: $surface;
    color: $ink;
    border-color: $line;
    &:hover { background: $page; border-color: #C9D2DE; }
  }

  &--lg { min-height: 48px; padding: $space-3 $space-6; }

  &--full { width: 100%; }

  &:disabled { opacity: 0.55; cursor: not-allowed; }
}

.btn__spinner {
  width: 16px; height: 16px;
  border: 2px solid rgba(255,255,255,0.4);
  border-top-color: #fff;
  border-radius: 50%;
  animation: spin 0.6s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

// ── Navbar ────────────────────────────────────────────────────────────────────
.navbar {
  position: sticky;
  top: 0;
  z-index: $z-sticky;
  background: $surface;
  border-bottom: 1px solid $line;

  &__inner {
    max-width: $container-max-width;
    margin: 0 auto;
    padding: $space-3 $container-padding;
    min-height: 68px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: $space-4;

    @media (max-width: #{$breakpoint-md - 1px}) { padding: $space-2 $container-padding-mobile; }
  }

  &__brand {
    display: flex;
    align-items: center;
    gap: $space-2;
    color: $blue-600;
    font-weight: 700;
    font-size: $font-size-lg;
    letter-spacing: -0.3px;
    flex-shrink: 0;
    min-height: $ctl-h;
    &:focus-visible { outline: none; box-shadow: $focus-ring; border-radius: $radius-md; }
  }

  &__logo-icon { font-size: 1.4rem; }
  &__auth {
    display: flex;
    align-items: center;
    gap: $space-2;
    flex-wrap: wrap;
    justify-content: flex-end;
  }

  &__center {
    display: flex;
    align-items: center;
    gap: $space-6;
    flex: 1;
    justify-content: center;

    @media (max-width: 767px) { display: none; }
  }

  &__link {
    display: inline-flex;
    align-items: center;
    min-height: $ctl-h;
    color: $ink-2;
    font-size: $font-size-base;
    font-weight: 500;
    &:hover, &:focus-visible { color: $blue-700; }
  }

  @media (max-width: 479px) {
    &__logo-text { display: none; }
    &__auth .btn { padding: $space-2 $space-3; font-size: $font-size-base; }
  }
}

// ── Hero ──────────────────────────────────────────────────────────────────────
.hero {
  background: $blue-50;
  padding: 88px 0 72px;

  &__inner {
    max-width: $container-max-width;
    margin: 0 auto;
    padding: 0 $container-padding;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 64px;
    align-items: center;
  }

  &__headline {
    font-size: clamp(2rem, 4vw, 3rem);
    font-weight: 700;
    color: $ink;
    line-height: 1.2;
    margin: 0 0 $space-5;
    letter-spacing: -0.5px;
  }

  &__subheadline {
    font-size: $font-size-lg;
    color: $ink-2;
    line-height: 1.7;
    margin: 0 0 $space-8;
  }

  &__actions {
    display: flex;
    align-items: center;
    gap: $space-6;
    flex-wrap: wrap;
  }

  &__secondary-cta {
    display: inline-flex;
    align-items: center;
    min-height: $ctl-h;
    color: $blue-700;
    font-weight: 600;
    font-size: $font-size-base;
    &:hover { text-decoration: underline; }
  }

  &__visual { display: flex; justify-content: center; }
}

.token-graphic {
  display: flex;
  align-items: center;
  gap: $space-4;
  background: $surface;
  border: 1px solid $line;
  border-radius: $radius-xl;
  padding: $space-8 $space-10;
  box-shadow: $shadow-card;
}

.token {
  display: flex; flex-direction: column; align-items: center; gap: 10px; width: 90px;

  &__icon {
    width: 64px; height: 64px; border-radius: 50%;
    background: $blue-50;
    display: flex; align-items: center; justify-content: center;
    font-size: 1.6rem; color: $blue-600;
  }

  &__label { font-size: $font-size-sm; font-weight: 600; color: $ink; text-align: center; }
  &--3 .token__icon { background: $ok-bg; color: $ok; }
}

.token-arrow { font-size: 1.5rem; color: $ink-2; }

// ── How It Works ──────────────────────────────────────────────────────────────
.how-it-works { padding: 80px 0; background: $surface; }

.hiw {
  &__steps { display: flex; align-items: flex-start; margin-top: $space-12; }
  &__step { flex: 1; text-align: center; padding: 0 $space-6; }
  &__step-number {
    width: 36px; height: 36px; border-radius: 50%;
    background: $blue-600; color: #fff;
    font-weight: 700; font-size: $font-size-base;
    display: inline-flex; align-items: center; justify-content: center; margin-bottom: $space-4;
  }
  &__step-icon { font-size: 2.4rem; display: block; margin-bottom: $space-4; }
  &__step-title { font-size: $font-size-lg; font-weight: 700; color: $ink; margin: 0 0 $space-2; }
  &__step-desc { font-size: $font-size-base; color: $ink-2; line-height: 1.6; margin: 0; }
  &__connector {
    width: 80px; height: 2px;
    background: $line;
    margin-top: 60px; flex-shrink: 0;
  }
}

// ── Value Proposition ─────────────────────────────────────────────────────────
.value-prop { padding: 80px 0; background: $page; }

.vp {
  &__cards {
    display: grid; grid-template-columns: repeat(4, 1fr); gap: $space-5; margin-top: $space-12;
  }
  &__card {
    background: $surface; border: 1px solid $line; border-radius: $radius-lg; padding: $space-6;
    box-shadow: $shadow-card;
    transition: border-color 0.15s;
    &:hover { border-color: $blue-600; }
  }
  &__card-icon { font-size: 2rem; margin-bottom: $space-4; display: block; }
  &__card-title { font-size: $font-size-md; font-weight: 700; color: $ink; margin: 0 0 $space-2; }
  &__card-desc { font-size: $font-size-base; color: $ink-2; line-height: 1.6; margin: 0; }
}

// ── Trust ─────────────────────────────────────────────────────────────────────
.trust {
  padding: 80px 0; background: $surface; text-align: center;

  &__mission {
    max-width: 640px; margin: 0 auto $space-12;
    font-size: $font-size-md; color: $ink-2; line-height: 1.75;
  }
  &__badges { display: flex; justify-content: center; gap: $space-4; flex-wrap: wrap; margin-bottom: 0; }
  &__badge {
    display: flex; align-items: center; gap: $space-3;
    background: $blue-50; border: 1px solid $line; border-radius: $radius-lg; padding: $space-3 $space-5;
    text-align: left;
    &-icon { font-size: 1.1rem; }
    &-text { font-size: $font-size-base; font-weight: 500; color: $blue-700; }
  }
}

// ── FAQ ───────────────────────────────────────────────────────────────────────
.faq {
  padding: 80px 0; background: $page;

  &__list { margin: $space-12 auto 0; max-width: 760px; }
  &__item {
    border: 1px solid $line; border-radius: $radius-lg; margin-bottom: $space-3;
    background: $surface; overflow: hidden;
    &--open { border-color: $blue-600; }
  }
  &__btn {
    width: 100%; display: flex; justify-content: space-between; align-items: center;
    padding: $space-4 $space-5; background: none; border: none; cursor: pointer;
    font-size: $font-size-md; font-weight: 600; color: $ink; text-align: left; gap: $space-4;
    min-height: $ctl-h; font-family: inherit;
    &:focus-visible { outline: none; box-shadow: inset $focus-ring; }
    &:hover { background: $page; }
  }
  &__chevron { font-size: 1.3rem; color: $blue-600; flex-shrink: 0; }
  &__answer { padding: 0 $space-5 $space-5; color: $ink-2; font-size: $font-size-base; line-height: 1.7; margin: 0; }
}

// ── Bottom CTA ────────────────────────────────────────────────────────────────
.bottom-cta {
  padding: 80px 0;
  background: $blue-600;
  text-align: center;

  &__inner { display: flex; flex-direction: column; align-items: center; gap: $space-5; }
  &__title { font-size: clamp(1.5rem, 3vw, 2rem); font-weight: 700; color: #fff; margin: 0; letter-spacing: -0.3px; }
  &__sub { font-size: $font-size-md; color: #fff; margin: 0; max-width: 480px; }
  &__btn { background: $surface; color: $blue-700; &:hover { background: $blue-50; } }
}

// ── Footer ────────────────────────────────────────────────────────────────────
.footer {
  background: $surface; border-top: 1px solid $line; padding: $space-12 0 $space-8;

  &__inner {
    max-width: $container-max-width; margin: 0 auto; padding: 0 $container-padding;
