      companyId: this.company.id,
      userName: this.userForm.userName.trim(),
      password: this.userForm.password
    };

    this.modalLoading = true;
    this.modalError = '';

    this.companyUserApi.create(dto).subscribe({
      next: _ => {
        this.modalLoading = false;
        this.closeModal();
        this.reloadUsers(true);
