@use '../../../../styles/variables' as v;

// Blue marketplace tokens (shared)
$primary:      v.$blue-600;
$primary-dark: v.$blue-700;
$primary-bg:   v.$blue-50;
$border:       v.$line;
$surface:      v.$surface;
$text:         v.$ink;
$text-muted:   v.$ink-2;
$success:      v.$ok;
$error:        v.$danger;

// ── Backdrop ──────────────────────────────────────────────────
.scan-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(v.$ink, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: v.$z-modal-backdrop;
  padding: v.$space-4;
}

// ── Modal ─────────────────────────────────────────────────────
.scan-modal {
  position: relative;
  background: $surface;
  border: 1px solid $border;
  border-radius: v.$radius-xl;
  width: 100%;
  max-width: 400px;
  max-height: calc(100dvh - 32px);
  overflow-y: auto;
  padding: v.$space-8 v.$space-6 v.$space-6;
  box-shadow: v.$shadow-pop;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: v.$space-5;

  @media (max-width: 479px) {
    padding: v.$space-8 v.$space-4 v.$space-4;
  }

  &__close {
    position: absolute;
    top: v.$space-2;
    right: v.$space-2;
    width: v.$ctl-h;
    height: v.$ctl-h;
    display: flex;
    align-items: center;
    justify-content: center;
    background: none;
    border: none;
    font-size: 24px;
    color: $text-muted;
    cursor: pointer;
    border-radius: v.$radius-md;
    line-height: 1;
    transition: background 0.15s, color 0.15s;
    &:hover { background: v.$page; color: $text; }
    &:focus-visible { outline: none; box-shadow: v.$focus-ring; }
  }

  &__header {
    text-align: center;
    width: 100%;
    padding-inline: v.$space-8;
  }

  &__title {
    font-size: v.$font-size-lg;
    font-weight: 700;
    color: $text;
    margin: 0 0 v.$space-1;
  }

  &__subtitle {
    font-size: v.$font-size-base;
    color: $text-muted;
    margin: 0;
  }

  // ── Camera ───────────────────────────────────────────────
  &__camera-wrap {
    position: relative;
    width: min(280px, 100%);
    aspect-ratio: 1 / 1;
    border-radius: v.$radius-xl;
    overflow: hidden;
    background: #000;
  }

  &__video {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;

    &--hidden {
      display: none;
    }
  }

  // ── Viewfinder overlay ────────────────────────────────────
  &__viewfinder {
    position: absolute;
    inset: 20px;
    pointer-events: none;
  }

  &__corner {
    position: absolute;
    width: 24px;
    height: 24px;
    border-color: #fff;
    border-style: solid;
    filter: drop-shadow(0 0 2px rgba(0, 0, 0, 0.6));

    &--tl { top: 0; left: 0; border-width: 3px 0 0 3px; border-radius: 4px 0 0 0; }
    &--tr { top: 0; right: 0; border-width: 3px 3px 0 0; border-radius: 0 4px 0 0; }
    &--bl { bottom: 0; left: 0; border-width: 0 0 3px 3px; border-radius: 0 0 0 4px; }
    &--br { bottom: 0; right: 0; border-width: 0 3px 3px 0; border-radius: 0 0 4px 0; }
  }

  &__scan-line {
    position: absolute;
    left: 0; right: 0;
    height: 2px;
    background: $primary;
    box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.8), 0 0 6px rgba(0, 0, 0, 0.5);
    animation: scan 2s ease-in-out infinite;
  }

  // ── Token details ─────────────────────────────────────────
  &__token-details {
    width: 100%;
    background: $surface;
    border: 1px solid $border;
    border-radius: v.$radius-lg;
    overflow: hidden;
  }

  // ── Footer ───────────────────────────────────────────────
  &__footer {
    width: 100%;
    display: flex;
    justify-content: center;
    gap: v.$space-3;

    &--confirm {
      justify-content: space-between;
    }

    .scan-btn {
      flex: 1;
    }

    @media (max-width: 479px) {
      flex-direction: column-reverse;
    }
  }

  // ── State (loading / error) ───────────────────────────────
  &__state {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: v.$space-3;
    padding: v.$space-6 0;
    color: $text-muted;
    font-size: v.$font-size-md;
    text-align: center;

    &--error {
      color: $error;
      background: v.$danger-bg;
      border-radius: v.$radius-md;
      width: 100%;
      padding: v.$space-4;
    }

    &-icon {
      font-size: 2.5rem;
    }
  }
}

// ── Token detail rows ─────────────────────────────────────────
.token-detail-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: v.$space-3;
  padding: v.$space-3 v.$space-4;
  border-bottom: 1px solid $border;

  &:last-child { border-bottom: none; }

  &__label {
    font-size: v.$font-size-xs;
    font-weight: 600;
    color: $text-muted;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    flex-shrink: 0;
  }

  &__value {
    font-size: v.$font-size-base;
    color: $text;
    font-weight: 500;
    text-align: right;
    min-width: 0;
    overflow-wrap: anywhere;

    &--highlight {
      color: v.$blue-700;
      font-size: v.$font-size-lg;
      font-weight: 700;
      background: $primary-bg;
      padding: 2px v.$space-2;
      border-radius: v.$radius-sm;
    }
  }
}

.mono { font-family: v.$font-family-mono; }

.token-detail-row--mono {
  align-items: flex-start;

  .token-detail-row__value {
    word-break: break-all;
    font-size: v.$font-size-xs;
  }
}

// ── Scan line animation ────────────────────────────────────────
@keyframes scan {
  0%   { top: 0; opacity: 0; }
  10%  { opacity: 1; }
  90%  { opacity: 1; }
  100% { top: 100%; opacity: 0; }
}

// ── Spinner ───────────────────────────────────────────────────
.scan-spinner {
  width: 40px;
  height: 40px;
  border: 3px solid $border;
  border-top-color: $primary;
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

// ── Buttons ───────────────────────────────────────────────────
.scan-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: v.$ctl-h;
  padding: v.$space-2 v.$space-5;
  border-radius: v.$radius-md;
  font-size: v.$font-size-md;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background 0.15s, border-color 0.15s, color 0.15s;

  &:focus-visible { outline: none; box-shadow: v.$focus-ring; }

  &--ghost {
    background: $surface;
    border-color: $border;
    color: $text;
    &:hover { background: v.$page; border-color: #C9D2DE; }
  }

  &--confirm {
    background: $primary;
    color: #fff;
    &:hover { background: $primary-dark; }
    &:disabled { opacity: 0.55; cursor: not-allowed; }
  }
}

