    try {
      const controls = await this.reader.decodeFromVideoDevice(
        undefined,
        video,
        result => {
          if (result) {
            void this.onQrDetected(result.getText());
          }
        }
      );
      if (this.destroyed) {
        // Component was torn down while the camera was still starting.
        controls.stop();
        return;
      }
      this.controls = controls;
    } catch {
